"""Core fraction question model shared by the game and storage layers."""

from dataclasses import dataclass
from enum import Enum
from fractions import Fraction


class QuestionType(Enum):
    """The kinds of fraction questions the game can ask."""

    ADD = "add"
    SUBTRACT = "subtract"
    MULTIPLY = "multiply"
    COMPARE = "compare"
    SIMPLIFY = "simplify"


@dataclass(frozen=True)
class Question:
    """A multiple-choice fraction question.

    All arithmetic is performed on ``fractions.Fraction`` values; answers are
    stored as display strings so they can be compared without floating point
    error.
    """

    id: int
    prompt: str
    options: tuple[str, ...]
    correct_answer: str
    question_type: QuestionType

    def is_correct(self, answer: str) -> bool:
        """Return True when ``answer`` matches the correct answer."""
        return answer.strip() == self.correct_answer.strip()


def fraction_to_text(value: Fraction) -> str:
    """Render a Fraction as a compact, human readable string."""
    if value.denominator == 1:
        return str(value.numerator)
    return f"{value.numerator}/{value.denominator}"
